// --- decode (Arrow → entity bags). ---

// agentrunentrySectionReaderI is the uniform slice of the generated read-access
// readers. Column indices stay at their constructor defaults — the
// schema order a SELECT * returns.
type agentrunentrySectionReaderI interface {
	LoadFromRecord(raruntime.RecordI) error
	Release()
}

func (inst *EntryStore) queryEntities(ctx context.Context, sql string) (ents []*EntryEntity, err error) {
	for rec, rerr := range inst.exec.QueryArrow(ctx, sql) {
		if rerr != nil {
			err = eh.Errorf("query entities: %w", rerr)
			return
		}
		batch, derr := decodeEntryRecord(rec)
		rec.Release()
		if derr != nil {
			err = derr
			return
		}
		ents = append(ents, batch...)
	}
	return
}

// iterateEntities adapts the buffered query path to the single-use
// iterator contract shared by Replay and the Scan verbs: entities
// yield in query order; an error yields once as (nil, err) and ends
// the sequence.
func (inst *EntryStore) iterateEntities(ctx context.Context, sql string) iter.Seq2[*EntryEntity, error] {
	return func(yield func(*EntryEntity, error) bool) {
		ents, err := inst.queryEntities(ctx, sql)
		if err != nil {
			yield(nil, err)
			return
		}
		for _, ent := range ents {
			if !yield(ent, nil) {
				return
			}
		}
	}
}

